export class SnakeController {
  private snake: { x: number; y: number; dir: 'left' | 'right' | 'up' | 'down' }[];
  private food: { x: number; y: number };
  private dir: 'left' | 'right' | 'up' | 'down';
  private gameRunning: boolean;
  private gridSize: number;
  private speed: number;

  constructor(gridSize: number, speed: number) {
    this.gridSize = gridSize;
    this.speed = speed;
    this.gameRunning = true;
    this.snake = [{ x: 4, y: 4 }, { x: 3, y: 4 }, { x: 2, y: 4 }];
    this.food = { x: 10, y: 10 };
    this.dir = 'right';
  }

  public getGameState(): { snake: { x: number; y: number }[]; food: { x: number; y: number }; running: boolean } {
    return { snake: this.snake.map(s => ({ x: s.x, y: s.y })), food: this.food, running: this.gameRunning };
  }

  public startGame(): void {
    this.gameRunning = true;
  }

  public stopGame(): void {
    this.gameRunning = false;
  }

  public move(): void {
    if (!this.gameRunning) return;

    const head = { x: this.snake[0].x, y: this.snake[0].y };
    const nextDir = this.dir;

    switch (nextDir) {
      case 'left':
        head.x--;
        break;
      case 'right':
        head.x++;
        break;
      case 'up':
        head.y--;
        break;
      case 'down':
        head.y++;
        break;
    }

    this.snake.unshift(head);

    if (head.x === this.food.x && head.y === this.food.y) {
      this.placeFood();
    } else {
      this.snake.pop();
    }

    if (!this.gameRunning) {
      this.snake = [{ x: 4, y: 4 }, { x: 3, y: 4 }, { x: 2, y: 4 }];
      this.food = { x: 10, y: 10 };
      this.dir = 'right';
    }
  }

  private placeFood(): void {
    const foodPlaced = false;
    if (foodPlaced) {
      this.food = { x: Math.floor(Math.random() * this.gridSize), y: Math.floor(Math.random() * this.gridSize) };
    }
  }
}

export class MovementEngine {
  private snake: { head: { x: number; y: number }; body: { x: number; y: number }[]; direction: 'up' | 'down' | 'left' | 'right' }[] = [];
  private gridSize: { width: number; height: number };
  private food: { x: number; y: number };
  private speed: number = 200;
  private direction: 'up' | 'down' | 'left' | 'right' = 'right';

  constructor(gridSize: { width: number; height: number }) {
    this.gridSize = gridSize;
    this.food = this.generateFood();
  }

  public addSnake(): void {
    this.snake.push({
      head: { x: 5, y: 5 },
      body: [{ x: 4, y: 5 }, { x: 3, y: 5 }],
      direction: 'right',
    });
  }

  public move(): void {
    this.snake.forEach((snake) => {
      const newHead = { ...snake.head };
      switch (snake.direction) {
        case 'up':
          newHead.y--;
          break;
        case 'down':
          newHead.y++;
          break;
        case 'left':
          newHead.x--;
          break;
        case 'right':
          newHead.x++;
          break;
      }
      newHead.x = (newHead.x + this.gridSize.width) % this.gridSize.width;
      newHead.y = (newHead.y + this.gridSize.height) % this.gridSize.height;
      snake.head = newHead;
      snake.body.unshift(newHead);
      if (!this.checkCollision(snake)) {
        snake.body.pop();
      }
    });
  }

  private checkCollision(snake: { head: { x: number; y: number }; body: { x: number; y: number }[]; direction: 'up' | 'down' | 'left' | 'right' }): boolean {
    const head = snake.head;
    for (const bodyPart of snake.body) {
      if (head.x === bodyPart.x && head.y === bodyPart.y) {
        return true;
      }
    }
    if (head.x < 0 || head.x >= this.gridSize.width || head.y < 0 || head.y >= this.gridSize.height) {
      return true;
    }
    return false;
  }

  private generateFood(): { x: number; y: number } {
    let x, y;
    do {
      x = Math.floor(Math.random() * this.gridSize.width);
      y = Math.floor(Math.random() * this.gridSize.height);
    } while (this.snake.some((s) => s.head.x === x && s.head.y === y));
    return { x, y };
  }

  public getScore(): number {
    return this.snake.length - 1;
  }

  public getSpeed(): number {
    return this.speed;
  }

  public setSpeed(newSpeed: number): void {
    this.speed = newSpeed;
  }

  public getFoodPosition(): { x: number; y: number } {
    return this.food;
  }

  public updateDirection(newDirection: 'up' | 'down' | 'left' | 'right'): void {
    this.direction = newDirection;
  }
}

