export function renderGrid(container: HTMLElement) {
    container.innerHTML = '<div style="display:flex;gap:10px;align-items:center"><div style="font-size:1.2rem;color:#e0e0f0">Score: <span style="color:#f87171">0</span></div><div style="font-size:1.2rem;color:#e0e0f0">Speed: <span style="color:#f472b6">5</span></div><div style="font-size:1.2rem;color:#e0e0f0">Game State: <span style="color:#a7c080">Running</span></div></div><div id="gameCanvas" style="width:400px;height:400px;border:1px solid #4a4a6a;background:#12121e"></div><div style="text-align:center;margin-top:10px"><button class="btn" onclick="restartGame()">🔄 Restart</button><button class="btn" onclick="togglePause()">⏸ Pause</button></div>';
    const canvas = document.getElementById('gameCanvas') as HTMLCanvasElement;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;
    canvas.width = 400;
    canvas.height = 400;
    const gridSize = 20;
    const cellSize = canvas.width / gridSize;
    let gameRunning = true;
    let snake = [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }];
    let food = { x: 15, y: 15 };
    let direction = { x: 0, y: 1 };
    let score = 0;
    let highScore = 0;
    let speed = 5;
    let lastUpdate = 0;
    const foods = [];
    const MAX_FOODS = 5;
    const GROWTH_PROBABILITY = 0.2;
    const GROWTH_REWARD = 10;
    const SNAKE_SPEED = 200;
    const canvasRect = canvas.getBoundingClientRect();
    const margin = { top: canvasRect.top, bottom: window.innerHeight - canvasRect.bottom, left: canvasRect.left, right: canvasRect.right };
    const update = () => {
        if (!gameRunning) return;
        const now = Date.now();
        if (now - lastUpdate < SNAKE_SPEED) return;
        lastUpdate = now;
        const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };
        snake.unshift(head);
        if (head.x === food.x && head.y === food.y) {
            score += 10;
            if (Math.random() < GROWTH_PROBABILITY) {
                foods.push({ x: head.x, y: head.y });
            }
            if (snake.length > 1 && snake.some(p => p.x === head.x && p.y === head.y)) {
                gameRunning = false;
                return;
            }
        } else {
            snake.pop();
        }
        for (let i = 0; i < foods.length; i++) {
            if (head.x === foods[i].x && head.y === foods[i].y) {
                foods[i] = null;
                score += 20;
                if (Math.random() < GROWTH_PROBABILITY) {
                    foods.push({ x: head.x, y: head.y });
                }
                if (snake.length > 1 && snake.some(p => p.x === head.x && p.y === head.y)) {
                    gameRunning = false;
                    return;
                }
            }
        }
        foods.filter(f => f !== null);
        if (head.x < 0 || head.x >= gridSize || head.y < 0 || head.y >= gridSize || snake.some(p => p.x === head.x && p.y === head.y)) {
            gameRunning = false;
            return;
        }
        if (!gameRunning) {
            setTimeout(() => { gameRunning = true; snake = [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }]; direction = { x: 0, y: 1 }; score = 0; }, 2000);
        }
    };
    const draw = () => {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = '#000';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        for (let i = snake.length - 1; i > 0; i--) {
            ctx.fillStyle = `rgba(0,255,0,${(snake.length - i) / 10})`;
            ctx.fillRect(snake[i].x * cellSize, snake[i].y * cellSize, cellSize, cellSize);
        }
        ctx.fillStyle = '#0f0';
        ctx.fillRect(snake[0].x * cellSize, snake[0].y * cellSize, cellSize, cellSize);
        ctx.fillStyle = '#f00';
        ctx.fillRect(food.x * cellSize, food.y * cellSize, cellSize, cellSize);
        for (let i = 0; i < foods.length; i++) {
            if (foods[i] !== null) {
                ctx.fillStyle = '#00f';
                ctx.fillRect(foods[i].x * cellSize, foods[i].y * cellSize, cellSize, cellSize);
            }
        }
    };
    const restartGame = () => {
        gameRunning = true;
        snake = [{ x: 10, y: 10 }, { x: 9, y: 10 }, { x: 8, y: 10 }];
        direction = { x: 0, y: 1 };
        score = 0;
        foods = [];
        speed = 5;
        lastUpdate = 0;
    };
    const togglePause = () => {
        gameRunning = !gameRunning;
    };
    const render = () => {
        update();
        draw();
        requestAnimationFrame(render);
    };
    render();
}
